// Convierte la respuesta de la API en un texto plano y verificable.
const d = $input.first().json.data;
if (!d || !Array.isArray(d.tickers)) {
  throw new Error('La API no devolvió la lista de activos.');
}

const lineas = d.tickers.map((t) => t.symbol + ': ' + t.last + ' USD (' + t.change_pct + '%), RSI ' + t.rsi14 + ', señal ' + t.signal);
const hechos = [
  'Sesión: ' + d.session,
  'Índice ' + d.index.name + ': ' + d.index.level + ' (' + d.index.change_pct + '%)',
  'Amplitud: ' + d.breadth.advancing + ' al alza / ' + d.breadth.declining + ' a la baja',
  '',
  ...lineas
].join('\n');

return [{ json: { hechos } }];

// Se queda solo con el texto del modelo y falla fuerte si vino vacío.
const respuesta = $input.first().json;
const texto = respuesta.choices && respuesta.choices[0] && respuesta.choices[0].message
  ? respuesta.choices[0].message.content
  : '';

if (!texto) {
  throw new Error('El modelo no devolvió texto. Revisá la credencial, el nombre del modelo y el saldo de la cuenta.');
}

return [{ json: { texto: texto.trim() } }];
